import {normalizeRevisionComparison,compareRevisionDocument} from './revision-comparison-model.mjs';
import {importWorkspaceDocument} from './document-import.mjs';
import {esc,icon} from './ui.mjs';

const pct=value=>(Number(value||0)*100).toFixed(1)+'%';
export function revisionComparisonMarkup(doc,index,{reportLabel='',hasHandoff=false,reportReady=false}={}){
 let comparison=null,error='';try{comparison=compareRevisionDocument(doc);}catch(e){error=e.message;}
 const direct=doc.reductionPath==='direct'||!doc.reductionPath&&!doc.comparison,part=comparison?.paragraphs.find(p=>p.paragraphId===doc.paragraphs[index]?.id),matched=comparison?.paragraphs.filter(p=>p.matches.length)||[];
 return `<section class="rev-source-workflow rev-report-entry" aria-label="降重依据与来源对照"><header><div><span class="rev-section-kicker">${direct?'直接降重':'按重复来源降重'}</span><h3>${reportReady?'按已确认的报告标记修改':'先明确重复在哪里，再处理重复表达'}</h3><p>重复率来自论文与其他文章的比对。原稿与修改稿的差异只用于审核修改，不作为降重分数。</p></div><span class="rev-source-status">${comparison?comparison.sources.length+' 份对照文章':reportLabel?'已有报告定位':'尚未添加对照文章'}</span></header><div class="rev-reduction-paths" role="group" aria-label="降重处理方式"><button type="button" class="btn ${direct?'secondary':'primary'}" data-rev-action="source-path" aria-pressed="${!direct}">按重复来源降重</button><button type="button" class="btn ${direct?'primary':'secondary'}" data-rev-action="direct-path" aria-pressed="${direct}">直接降重</button></div><div class="rev-source-actions"><button type="button" class="btn secondary" data-rev-action="sources">${icon('plus',15)}${comparison?'管理对照文章':'添加对照文章'}</button><button type="button" class="btn secondary" data-rev-action="report">导入查重报告</button>${hasHandoff?'<button type="button" class="btn secondary" data-rev-action="comparison-handoff">使用 PaperKnow 查重结果</button>':'<a class="btn secondary" href="#category/detection">使用 PaperKnow 查重结果</a>'}</div>${reportLabel?`<p class="rev-source-report-note">${esc(reportLabel)}；此报告仅用于定位原文，不据此计算新的重复率。</p>`:'<p class="rev-source-report-note">已有知网、维普、万方等报告可定位标记段落；添加实际对照正文后，才能核对本次来源范围内的相似占比。</p>'}${error?`<p class="rev-source-error" role="alert">${esc(error)}</p>`:''}${comparison?`<section class="rev-source-metrics" aria-label="本次来源范围内的比对结果"><div><small>本次来源范围内 · 原稿相似占比</small><strong>${pct(comparison.before.ratio)}</strong></div><div><small>同一来源范围 · 已采纳稿相似占比</small><strong>${pct(comparison.after.ratio)}</strong></div><div><small>原稿命中段落</small><strong>${matched.length}<em> / ${doc.paragraphs.length} 段</em></strong></div></section><p class="rev-source-boundary">以上结果由论文正文与这 ${comparison.sources.length} 份实际对照正文逐字比对；已采纳稿包含未修改的原文。不是学校数据库的重复率，也不覆盖未提供的文章。</p><div class="rev-source-list">${comparison.sources.map(source=>`<span>${icon('file',14)}${esc(source.name)}</span>`).join('')}</div><div class="rev-source-evidence" aria-label="当前段落来源证据"><h4>第 ${index+1} 段 · ${part?.matches.length?'命中来源片段':'未发现符合规则的匹配'}</h4>${part?.matches.length?part.matches.slice(0,8).map(match=>`<article><div class="rev-source-match-title"><b>${esc(match.name)}</b>${match.url?`<a href="${esc(match.url)}" target="_blank" rel="noopener noreferrer">打开来源 ${icon('link',12)}</a>`:''}</div><div class="rev-source-match-grid"><section><small>论文中的相似片段</small><pre>${esc(match.originalExcerpt)}</pre></section><section><small>对照文章中的片段</small><pre>${esc(match.sourceExcerpt)}</pre></section></div></article>`).join(''):'<p>本段未纳入来源降重的默认选区。可切换到有命中的段落，或明确选择“直接降重”。</p>'}${part?.matches.length>8?'<p>先展示 8 条匹配，全部来源与比对结果仍保留。</p>':''}</div><button type="button" class="btn secondary" data-rev-action="select-source-matches" ${!matched.length?'disabled':''}>选择全部命中段落（${matched.length} 段）</button>`:`<div class="rev-source-empty"><b>${direct?'当前选择：直接降重':reportReady?'已确认报告标记，可直接生成修改候选':'选择一项重复依据，开始针对性降重'}</b><p>${direct?'在保留研究含义、数据和引用的前提下调整表达。尚未与其他文章比对，不显示降重前后重复率。':reportReady?'本次只修改已核对的标记范围。无需再次添加对照文章；修改完成后可另行检测确认结果。':'可添加有权使用的对照文章，或先在论文检测中查找公开来源。只上传自己的论文，不能确定它与哪些文章重复。'}</p></div>`}</section>`;
}

/** Source text is independently reviewed and saved; it never replaces the manuscript. */
export function openRevisionSources({doc,getDocument=()=>doc,modal,onConfirm,notify=()=>{},isCurrent=()=>true,importDocument=importWorkspaceDocument}={}){
 const document=globalThis.document,win=document.defaultView,identity=getDocument()?.id,route=win.location.hash;
 let sources=[];if(getDocument()?.comparison)sources=normalizeRevisionComparison(getDocument().comparison).sources;
 modal('添加对照文章',`<section class="rev-source-dialog"><p>添加论文可能重复的其他文章正文或明确节选。仅用于本次来源比对，不会替换你的论文原文。</p><div data-source-existing>${sources.map(source=>`<div class="rev-source-saved"><span><b>${esc(source.name)}</b><small>${source.text.length.toLocaleString('zh-CN')} 字符</small></span><button class="btn secondary" type="button" data-source-remove="${esc(source.id)}">移除</button></div>`).join('')}</div><label for="rev-source-name">对照文章名称<input id="rev-source-name" maxlength="200" placeholder="填写文章题目或材料名称"></label><label for="rev-source-url">来源网址（可选）<input id="rev-source-url" maxlength="2000" placeholder="https://"></label><label class="rev-source-upload">${icon('upload',17)}上传对照文章<input type="file" data-source-file accept=".txt,.docx,.pdf" aria-label="上传对照文章" data-file-library-label="从文件管理选择对照文章"></label><p data-source-import-status role="status">TXT / DOCX 本地提取；PDF 需单独确认云端解析。</p><label for="rev-source-text">对照正文或明确节选<textarea id="rev-source-text" rows="7" maxlength="12000" placeholder="粘贴其他文章的实际正文；每份最多 12,000 字符，不会自动截断。"></textarea></label><p class="hub-footnote">最多 8 份来源，合计最多 24,000 字符。请只提供有权使用的材料；网址仅记录来源，不会自动抓取网页。</p><div class="rev-source-dialog-actions"><button type="button" class="btn secondary" data-source-add>添加这份文章</button><button type="button" class="btn primary" data-source-confirm>比对并保存来源</button></div><p data-source-error role="alert"></p></section>`);
 const host=document.querySelector('.rev-source-dialog'),$=s=>host.querySelector(s),dialog=host.closest('dialog'),opened=dialog?.open;
 let live=true,reading=false,generation=0,parseController=null,committing=false,observer;
 const current=()=>live&&host.isConnected&&(!opened||dialog.open)&&getDocument()?.id===identity&&win.location.hash===route&&isCurrent();
 function dispose(){if(!live)return;live=false;generation++;parseController?.abort();observer?.disconnect();win.removeEventListener('hashchange',dispose);dialog?.removeEventListener('close',dispose);}
 function controls(){for(const node of host.querySelectorAll('button,input,textarea'))node.disabled=reading||committing;}
 function render(){const target=$('[data-source-existing]');target.innerHTML=sources.map(source=>`<div class="rev-source-saved"><span><b>${esc(source.name)}</b><small>${source.text.length.toLocaleString('zh-CN')} 字符</small></span><button class="btn secondary" type="button" data-source-remove="${esc(source.id)}">移除</button></div>`).join('');target.querySelectorAll('[data-source-remove]').forEach(button=>button.onclick=()=>{if(current()&&!reading&&!committing){sources=sources.filter(source=>source.id!==button.dataset.sourceRemove);render();}});}
 function addPending(){const text=$('#rev-source-text').value;if(!text.trim())return false;const name=$('#rev-source-name').value.trim();if(!name)throw Error('请填写对照文章名称。');let number=1;while(sources.some(source=>source.id==='source-'+number))number++;sources=normalizeRevisionComparison({version:1,sources:[...sources,{id:'source-'+number,name,text,...($('#rev-source-url').value.trim()?{url:$('#rev-source-url').value.trim()}:{})}]}).sources;$('#rev-source-text').value='';$('#rev-source-name').value='';$('#rev-source-url').value='';render();return true;}
 $('[data-source-add]').onclick=()=>{if(!current()||reading||committing)return;try{if(!addPending())throw Error('请先填写对照正文。');$('[data-source-error]').textContent='';}catch(error){$('[data-source-error]').textContent=error.message;}};
 $('[data-source-confirm]').onclick=async()=>{if(!current()||reading||committing)return;try{addPending();const comparison=normalizeRevisionComparison({version:1,sources});compareRevisionDocument({...getDocument(),comparison});committing=true;controls();await onConfirm(comparison);if(!current())return;notify('已保存对照文章，并按实际来源定位重复片段；论文原文没有被替换。');dispose();dialog?.close();}catch(error){if(current()){$('[data-source-error]').textContent=error.message||'来源未能保存，请重试。';committing=false;controls();}}};
 $('[data-source-file]').onchange=async event=>{const file=event.target.files?.[0];if(!file||!current()||committing)return;const request=++generation,typedBefore=$('#rev-source-text').value,controller=new win.AbortController();parseController?.abort();parseController=controller;const owns=()=>current()&&request===generation&&!controller.signal.aborted,status=$('[data-source-import-status]');try{if(!/\.(txt|docx|pdf)$/i.test(file.name)||file.size>(/\.pdf$/i.test(file.name)?20:50)*1024*1024)throw Error('请选择有效的 TXT / DOCX（50MB以内）或 PDF（20MB以内）。');reading=true;controls();const extracted=await importDocument(file,status,{signal:controller.signal});if(!owns())return;if(typeof extracted.text!=='string'||!extracted.text.trim()||extracted.text.length>12000)throw Error('对照正文为空或超过 12,000 字符，请粘贴需要比对的明确节选；不会截断全文。');const adopt=()=>{if(!owns())return;$('#rev-source-text').value=extracted.text;if(!$('#rev-source-name').value.trim())$('#rev-source-name').value=file.name.replace(/\.[^.]+$/,'');status.textContent='已提取对照正文，请核对后添加；尚未保存或提交 AI。';};if(typedBefore.trim()||$('#rev-source-text').value!==typedBefore){status.textContent='文件已提取，当前输入仍保留。';const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='采用提取的对照正文';button.onclick=adopt;status.append(button);}else adopt();}catch(error){if(owns())status.textContent=error.message||'对照文章提取失败。';}finally{if(owns()){reading=false;controls();}}};
 render();win.addEventListener('hashchange',dispose);dialog?.addEventListener('close',dispose);if(win.MutationObserver){observer=new win.MutationObserver(()=>{if(!current())dispose();});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});}return{dispose};
}
